#!/usr/bin/env bash
# DAC v1.3.5 Installer  |  bash install-dac.sh [API_KEY] [MODEL]
set -euo pipefail

API_KEY="${1:-}"
MODEL="${2:-gpt-4o}"
DEST="${HOME}/NEXTGENWORLD+HUMAN_AI"

echo ""
echo "DAC v1.3.5 Installer → $DEST"
echo ""

# --- package manager ---
echo "[1/7] Detecting package manager..."
if command -v pkg >/dev/null 2>&1; then PM="pkg";
elif command -v apt-get >/dev/null 2>&1; then PM="apt";
else echo "ERROR: need pkg or apt"; exit 1; fi
echo "  $PM"

# --- preflight: catch corrupted binaries before anything else ---
echo "[2/7] Preflight integrity check..."
BROKEN=""
if [ -n "${PREFIX:-}" ] && [ -d "$PREFIX/bin" ]; then
  BROKEN=$(find "$PREFIX/bin" -maxdepth 1 -type f -size 0 2>/dev/null | head -20)
elif [ -d /usr/bin ]; then
  BROKEN=$(find /usr/bin -maxdepth 1 -type f -size 0 2>/dev/null | head -20)
fi
if [ -n "$BROKEN" ]; then
  echo "  WARNING: 0-byte binaries detected — the install shell is corrupt."
  echo "$BROKEN" | sed 's/^/    /'
  echo "  Attempting repair: $PM reinstall of owning packages..."
  for f in $BROKEN; do
    OWNER=$(dpkg -S "$f" 2>/dev/null | cut -d: -f1 | head -1 || true)
    if [ -n "$OWNER" ]; then
      echo "    Reinstalling $OWNER (owns $(basename "$f"))..."
      if [ "$PM" = "pkg" ]; then pkg reinstall -y "$OWNER" >/dev/null 2>&1 || true;
      else apt-get install --reinstall -y "$OWNER" >/dev/null 2>&1 || true; fi
    fi
  done
  BIN_DIR=""
  if [ -n "${PREFIX:-}" ] && [ -d "$PREFIX/bin" ]; then BIN_DIR="$PREFIX/bin"; fi
  if [ -z "$BIN_DIR" ] && [ -d /usr/bin ]; then BIN_DIR=/usr/bin; fi
  if [ -n "$BIN_DIR" ]; then
    REMAIN=$(find "$BIN_DIR" -maxdepth 1 -type f -size 0 2>/dev/null | head -5 || true)
    if [ -n "$REMAIN" ]; then
      echo "  ERROR: corruption persists. Fix on Android:"
      echo "    Settings → Apps → Termux → Storage → Clear data"
      echo "  then reopen Termux and rerun this installer."
      echo "$REMAIN" | sed 's/^/    /'
      exit 1
    fi
  fi
  echo "  Repaired."
else
  echo "  OK — no 0-byte binaries found."
fi

# --- install deps ---
echo "[3/7] Installing python, git, tmux..."
if [ "$PM" = "pkg" ]; then
  pkg update -y 2>/dev/null || true
  pkg install -y python git tmux 2>/dev/null || true
else
  apt-get update -y 2>/dev/null || true
  apt-get install -y python3 python3-pip git tmux 2>/dev/null || true
fi

# --- dirs ---
echo "[4/7] Creating $DEST..."
mkdir -p "$DEST/dac/commands" "$DEST/dac/core" "$DEST/gcia"

# --- write source files ---
echo "[5/7] Writing source files..."
echo 'IiIiRGVjZW50cmFsaXplZCBBdXRvbm9tb3VzIENvZGVyIChEQUMpIOKAlCBBSS1wb3dlcmVkIGNvZGluZyBmcm9tIHlvdXIgcGhvbmUuIiIiCl9fdmVyc2lvbl9fID0gIjEuMy41Igo=' | base64 -d > "$DEST/dac/__init__.py"
echo 'IiIiQWxsb3cgcnVubmluZyBhcyBgcHl0aG9uIC1tIGRhY2AuIiIiCmltcG9ydCBzeXMKZnJvbSBkYWMubGF1bmNoZXIgaW1wb3J0IG1haW4KaWYgX19uYW1lX18gPT0gIl9fbWFpbl9fIjoKICAgIHN5cy5leGl0KG1haW4oKSkK' | base64 -d > "$DEST/dac/__main__.py"
echo '' | base64 -d > "$DEST/dac/config.py"
echo '' | base64 -d > "$DEST/dac/launcher.py"
echo '' | base64 -d > "$DEST/dac/cli.py"
echo '' | base64 -d > "$DEST/dac/repl.py"
echo '' | base64 -d > "$DEST/dac/daemon.py"
echo '' | base64 -d > "$DEST/dac/orchestrator.py"
echo '' | base64 -d > "$DEST/dac/assistant.py"
echo '' | base64 -d > "$DEST/dac/monitor.py"
echo '' | base64 -d > "$DEST/dac/telegram_bot.py"
echo '' | base64 -d > "$DEST/dac/demo.py"
echo '' | base64 -d > "$DEST/dac/site.py"
echo 'IiIiREFDIGNvbW1hbmQgbW9kdWxlcy4iIiIK' | base64 -d > "$DEST/dac/commands/__init__.py"
echo 'IiIiREFDIGNvcmUgZW5naW5lIG1vZHVsZXMuIiIiCg==' | base64 -d > "$DEST/dac/core/__init__.py"
echo '' | base64 -d > "$DEST/dac/core/llm.py"
echo '' | base64 -d > "$DEST/dac/core/executor.py"
echo '' | base64 -d > "$DEST/dac/core/session.py"
echo '' | base64 -d > "$DEST/dac/core/autonomous.py"
echo 'IiIiR0NJQSDigJQgR2xvYmFsIEN5YmVyIEludGVsbGlnZW5jZSBBZ2VuY3kgKGludmVzdGlnYXRpb24gKyByZWd1bGF0b3J5IGJyYW5jaGVzKS4iIiIKCl9fdmVyc2lvbl9fID0gIjAuNi4wIgo=' | base64 -d > "$DEST/gcia/__init__.py"
echo 'IiIiQWxsb3cgcnVubmluZyBhcyBgcHl0aG9uIC1tIGdjaWFgLiIiIgppbXBvcnQgc3lzCmZyb20gZ2NpYS5sYXVuY2hlciBpbXBvcnQgbWFpbgoKaWYgX19uYW1lX18gPT0gIl9fbWFpbl9fIjoKICAgIHN5cy5leGl0KG1haW4oKSkK' | base64 -d > "$DEST/gcia/__main__.py"
echo '' | base64 -d > "$DEST/gcia/audit.py"
echo '' | base64 -d > "$DEST/gcia/laptop.py"
echo '' | base64 -d > "$DEST/gcia/launcher.py"
echo '' | base64 -d > "$DEST/gcia/policy.py"
echo '' | base64 -d > "$DEST/gcia/recon.py"
echo '' | base64 -d > "$DEST/gcia/vault.py"
echo '' | base64 -d > "$DEST/gcia/notify.py"
echo '' | base64 -d > "$DEST/gcia/patrol.py"
echo '' | base64 -d > "$DEST/gcia/remote.py"
echo '' | base64 -d > "$DEST/gcia/agent.py"
echo '' | base64 -d > "$DEST/setup.py"
echo '' | base64 -d > "$DEST/README.md"

# --- install ---
echo "[6/7] Installing DAC globally..."
cp "$DEST/gcia-agent" /usr/local/bin/gcia-agent 2>/dev/null || true
chmod +x /usr/local/bin/gcia-agent 2>/dev/null || true
cp "$DEST/gcia-agent" "$PREFIX/bin/gcia-agent" 2>/dev/null || true
chmod +x "$PREFIX/bin/gcia-agent" 2>/dev/null || true
cd "$DEST"
PIP_FLAGS=""
if [ "$PM" = "apt" ]; then PIP_FLAGS="--break-system-packages"; fi
python3 -m pip install $PIP_FLAGS -e . 2>/dev/null || python3 -m pip install $PIP_FLAGS . 2>/dev/null

# --- configure ---
echo "[7/7] Configuring..."
if [ -n "$API_KEY" ]; then
  python3 -c "
from dac.config import load_config, save_config
cfg = load_config()
cfg['api_key'] = '$API_KEY'
cfg['model'] = '$MODEL'
save_config(cfg)
print('API key: sk-***' + '$API_KEY'[-4:])
  "
fi

# --- smoke test ---
echo ""
if dac run 'print("DAC installed OK")'; then
  echo ""
  echo "=== DAC v1.3.5 ready ==="
  echo ""
  echo "  dac --version"
  echo "  dac doctor"
  echo "  dac doctor --fix"
  echo "  dac assistant --say hi"
  echo "  dac monitor --add BTC"
  echo "  dac demo"
  echo "  dac quick \"your task\""
  echo "  dac daemon start"
  echo ""
else
  echo "WARNING: smoke test failed"
fi
